<?php require_once __DIR__.'/includes/permissions.php';require_permission('reports.view');$pdo=db();$from=get('from','');$to=get('to','');$barangay=get('barangay','');$service=(int)get('service',0);$where=['1=1'];$params=[];if($from){$where[]='a.appointment_date>=?';$params[]=$from;}if($to){$where[]='a.appointment_date<=?';$params[]=$to;}if($barangay){$where[]='r.barangay=?';$params[]=$barangay;}if($service){$where[]='a.service_id=?';$params[]=$service;}$q=$pdo->prepare('SELECT a.reference_no,r.patient_id,r.first_name,r.last_name,r.barangay,s.name service_name,a.appointment_date,a.appointment_time,a.status FROM appointments a LEFT JOIN residents r ON r.id=a.resident_id JOIN services s ON s.id=a.service_id WHERE '.implode(' AND ',$where).' ORDER BY a.appointment_date DESC,a.appointment_time');$q->execute($params);$rows=$q->fetchAll();$services=active_services();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Reports</h1><p>Filter operational data and print/export the current result.</p></div><button class="btn btn-outline-primary" onclick="window.print()"><i class="bi bi-printer"></i> Print</button></div><div class="panel mb-4"><form method="get" class="row g-2"><div class="col-md-2"><label>From</label><input type="date" name="from" value="<?=e($from)?>" class="form-control"></div><div class="col-md-2"><label>To</label><input type="date" name="to" value="<?=e($to)?>" class="form-control"></div><div class="col-md-3"><label>Barangay</label><select name="barangay" class="form-select"><option value="">All</option><?php foreach(all_barangays() as $b):?><option <?=$barangay===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Service</label><select name="service" class="form-select"><option value="">All</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$service===$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Generate</button></div></form></div><div class="panel"><div class="panel-head"><h5>Appointment Report <span class="small text-muted"><?=count($rows)?> records</span></h5><button class="btn btn-sm btn-outline-secondary" id="exportCsv">Export CSV</button></div><div class="table-responsive"><table class="table" id="reportTable"><thead><tr><th>Reference</th><th>Patient ID</th><th>Barangay</th><th>Service</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reference_no'])?></td><td><?=e($r['patient_id']??'—')?></td><td><?=e($r['barangay']??'—')?></td><td><?=e($r['service_name'])?></td><td><?=e($r['appointment_date'])?></td><td><?=e($r['appointment_time'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><script>document.getElementById('exportCsv').onclick=()=>{let rows=[...document.querySelectorAll('#reportTable tr')].map(tr=>[...tr.cells].map(c=>'"'+c.innerText.replaceAll('"','""')+'"').join(','));let b=new Blob([rows.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='chms_report.csv';a.click();};</script><?php include __DIR__.'/includes/footer.php'; ?>
